CREATE TABLE project_checklist_template_items ( id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NOT NULL, seq INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, required_perm TEXT, due_offset_days INTEGER, section_id INTEGER REFERENCES project_checklist_template_sections(id) ON DELETE SET NULL, requires_review INTEGER NOT NULL DEFAULT 0, role_label TEXT, crew_visible INTEGER NOT NULL DEFAULT 0, pill_kind TEXT, pill_value TEXT, FOREIGN KEY (template_id) REFERENCES project_checklist_templates(id) ON DELETE CASCADE );
CREATE TABLE project_checklist_template_sections ( id INTEGER PRIMARY KEY AUTOINCREMENT, template_id INTEGER NOT NULL, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), display_mode TEXT NOT NULL DEFAULT 'list', FOREIGN KEY (template_id) REFERENCES project_checklist_templates(id) ON DELETE CASCADE );
CREATE TABLE project_checklist_templates ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE project_cost_rates ( id INTEGER PRIMARY KEY AUTOINCREMENT, brand TEXT NOT NULL UNIQUE, transport_pct REAL NOT NULL DEFAULT 0, merchandise_pct REAL NOT NULL DEFAULT 0, commission_normal_pct REAL NOT NULL DEFAULT 0, commission_boost_pct REAL, boost_min_gp_pct REAL, boost_min_sales REAL, updated_at TEXT DEFAULT (datetime('now')), updated_by INTEGER );
CREATE TABLE project_defects ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, phase TEXT NOT NULL CHECK (phase IN ('setup', 'dismantle')), reported_by_role TEXT NOT NULL CHECK (reported_by_role IN ('sales', 'logistic')), item_code TEXT, item_description TEXT, size TEXT, quantity INTEGER DEFAULT 1, reason TEXT, photo_r2_key TEXT, reported_by INTEGER, reported_at TEXT DEFAULT (datetime('now')), resolved INTEGER DEFAULT 0, resolved_notes TEXT, linked_assr_id INTEGER, archived_at TEXT, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY (linked_assr_id) REFERENCES assr_cases(id) ON DELETE SET NULL );
CREATE TABLE project_event_types ( id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, default_template_id INTEGER, sort_order INTEGER DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE project_finance ( project_id INTEGER PRIMARY KEY, rental REAL, contractor_cost REAL, license_fee REAL, deposit_paid REAL, deposit_refund REAL, misc_cost REAL, total_sales REAL, notes TEXT, updated_at TEXT DEFAULT (datetime('now')), updated_by INTEGER, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE );
CREATE TABLE project_finance_lines ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('income', 'cost')), category TEXT NOT NULL, description TEXT, amount REAL NOT NULL, occurred_at TEXT, r2_key TEXT, file_name TEXT, mime_type TEXT, notes TEXT, created_by INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), archived_at TEXT, auto_source TEXT, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE );
CREATE TABLE project_organizers ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, notes TEXT, active INTEGER NOT NULL DEFAULT 1, created_by INTEGER, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE project_phase_photos ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, phase TEXT NOT NULL CHECK (phase IN ('setup','dismantle')), r2_key TEXT NOT NULL, content_type TEXT, caption TEXT, uploaded_by INTEGER REFERENCES users(id), uploaded_at TEXT NOT NULL DEFAULT (datetime('now')) );
CREATE TABLE project_reads ( user_id INTEGER NOT NULL, project_id INTEGER NOT NULL, last_read_at TEXT DEFAULT (datetime('now')), PRIMARY KEY (user_id, project_id), FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE );
CREATE TABLE project_sales_attendees ( project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, sales_rep_id INTEGER NOT NULL REFERENCES sales_reps(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT (datetime('now')), created_by INTEGER, PRIMARY KEY (project_id, sales_rep_id) );
CREATE TABLE project_sales_reports ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, title TEXT, sales_amount REAL, period_start TEXT, period_end TEXT, r2_key TEXT, file_name TEXT, mime_type TEXT, uploaded_by INTEGER, created_at TEXT DEFAULT (datetime('now')), archived_at TEXT, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE );
CREATE TABLE project_stock_transfers ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, direction TEXT NOT NULL CHECK (direction IN ('out', 'return')), transferred_at TEXT, record_r2_key TEXT, file_name TEXT, mime_type TEXT, notes TEXT, confirmed_at TEXT, confirmed_by INTEGER, created_by INTEGER, created_at TEXT DEFAULT (datetime('now')), archived_at TEXT, FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE );
CREATE TABLE project_team ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, user_id INTEGER NOT NULL, role TEXT, created_at TEXT DEFAULT (datetime('now')), FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE, UNIQUE (project_id, user_id, role) );
CREATE TABLE project_venues ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, state TEXT, notes TEXT, active INTEGER NOT NULL DEFAULT 1, created_by INTEGER, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE "projects" ( id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT UNIQUE, name TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'draft' CHECK (stage IN ('draft','setup','live','dismantle','completed')), start_date TEXT, end_date TEXT, organizer TEXT, state TEXT, venue TEXT, venue_address TEXT, brand TEXT, event_type_id INTEGER, booth_no TEXT, size_sqm REAL, notion_url TEXT, notes TEXT, created_by INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), archived_at TEXT, archived_by INTEGER, setup_start_at TEXT, setup_end_at TEXT, dismantle_start_at TEXT, dismantle_end_at TEXT, setup_driver_user_id INTEGER, setup_lorry_id INTEGER, dismantle_driver_user_id INTEGER, dismantle_lorry_id INTEGER, banner_message TEXT, banner_tone TEXT, payment_status TEXT DEFAULT 'not_started', payment_proof_r2_key TEXT, payment_proof_file_name TEXT, payment_notes TEXT, payment_updated_at TEXT, payment_updated_by INTEGER, pic_id INTEGER, setup_helper_1_id INTEGER REFERENCES users(id), setup_helper_2_id INTEGER REFERENCES users(id), setup_helper_outsourced INTEGER NOT NULL DEFAULT 0, dismantle_helper_1_id INTEGER REFERENCES users(id), dismantle_helper_2_id INTEGER REFERENCES users(id), dismantle_helper_outsourced INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending', setup_crew TEXT, dismantle_crew TEXT, service_crew TEXT, schedule_remark TEXT, FOREIGN KEY (event_type_id) REFERENCES project_event_types(id) ON DELETE SET NULL, FOREIGN KEY (pic_id) REFERENCES users(id) ON DELETE SET NULL );
CREATE TABLE purchase_order_docs ( doc_no TEXT PRIMARY KEY, doc_date TEXT, ref TEXT, so_doc_no TEXT, creditor_code TEXT, creditor_name TEXT, purchase_location TEXT, doc_status TEXT, cancelled INTEGER DEFAULT 0, local_ex_tax REAL, local_tax REAL, local_net_total REAL, final_total REAL, currency_code TEXT, currency_rate REAL, remark1 TEXT, remark2 TEXT, remark3 TEXT, remark4 TEXT, note TEXT, last_modified TEXT, amount_source TEXT, amount_updated_at TEXT, amount_updated_by INTEGER, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP , raw TEXT);
CREATE TABLE purchase_orders ( id INTEGER PRIMARY KEY AUTOINCREMENT, doc_no TEXT NOT NULL, so_doc_no TEXT, creditor_code TEXT, creditor_name TEXT, item_code TEXT NOT NULL, item_description TEXT, location TEXT, doc_date TEXT, remaining_qty REAL, delivery_date TEXT, supplier_date1 TEXT, supplier_date2 TEXT, supplier_date3 TEXT, overdue_days TEXT, unit_price REAL, amount REAL, amount_source TEXT, amount_updated_at TEXT, amount_updated_by INTEGER, original_qty REAL, is_outstanding INTEGER DEFAULT 0, doc_status TEXT, cancelled INTEGER DEFAULT 0, UNIQUE(doc_no, item_code) );
CREATE TABLE role_page_access ( role_id INTEGER NOT NULL REFERENCES roles(id) ON DELETE CASCADE, page_key TEXT NOT NULL, level TEXT NOT NULL CHECK (level IN ('none','partial','full')), created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), PRIMARY KEY (role_id, page_key) );
CREATE TABLE roles ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT UNIQUE NOT NULL, description TEXT, permissions TEXT NOT NULL DEFAULT '[]', is_system INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT (datetime('now')) , scope_to_pic INTEGER NOT NULL DEFAULT 0);
CREATE TABLE salary_records ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, period TEXT NOT NULL, base_pay REAL DEFAULT 0, trip_count INTEGER DEFAULT 0, trip_allowance_total REAL DEFAULT 0, ot_hours REAL DEFAULT 0, ot_amount REAL DEFAULT 0, deductions_json TEXT DEFAULT '[]', deductions_total REAL DEFAULT 0, gross REAL DEFAULT 0, net REAL DEFAULT 0, status TEXT DEFAULT 'draft' CHECK(status IN ('draft','confirmed','paid')), confirmed_by INTEGER, confirmed_at TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), UNIQUE(user_id, period), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (confirmed_by) REFERENCES users(id) );
CREATE TABLE salary_trip_lines ( id INTEGER PRIMARY KEY AUTOINCREMENT, salary_record_id INTEGER, user_id INTEGER NOT NULL, trip_id INTEGER NOT NULL, trip_date TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('driver','helper')), trip_allowance REAL DEFAULT 0, ot_hours REAL DEFAULT 0, ot_amount REAL DEFAULT 0, notes TEXT, created_at TEXT DEFAULT (datetime('now')), UNIQUE(user_id, trip_id), FOREIGN KEY (salary_record_id) REFERENCES salary_records(id), FOREIGN KEY (user_id) REFERENCES users(id), FOREIGN KEY (trip_id) REFERENCES trips(id) );
CREATE TABLE sales_commission_tiers ( id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, rate REAL NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_entries ( id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER REFERENCES projects(id) ON DELETE SET NULL, customer_name TEXT NOT NULL, customer_code TEXT, amount REAL NOT NULL, currency TEXT NOT NULL DEFAULT 'MYR', occurred_at TEXT NOT NULL, notes TEXT, status TEXT NOT NULL DEFAULT 'draft', autocount_doc_no TEXT, autocount_doc_type TEXT, pushed_at TEXT, push_error TEXT, created_by INTEGER NOT NULL, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), archived_at TEXT, ref_no TEXT, deposit_amount REAL, deposit_payment_type TEXT, sales_person_id INTEGER REFERENCES users(id), customer_address TEXT, customer_phone TEXT, sales_rep_id INTEGER REFERENCES sales_reps(id) ON DELETE SET NULL, doc_no TEXT, processing_date TEXT, delivery_date TEXT, status_2 TEXT, customer_address_2 TEXT, customer_postcode TEXT, customer_state TEXT, customer_phone_2 TEXT, customer_email TEXT, venue TEXT, warehouse TEXT, branding TEXT, po_doc_no TEXT, payment_status TEXT, source TEXT, remarks TEXT, FOREIGN KEY (created_by) REFERENCES users(id) );
CREATE TABLE sales_entry_activity ( id INTEGER PRIMARY KEY AUTOINCREMENT, entry_id INTEGER NOT NULL, user_id INTEGER, action TEXT NOT NULL, note TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_entry_change_requests ( id INTEGER PRIMARY KEY AUTOINCREMENT, entry_id INTEGER NOT NULL REFERENCES sales_entries(id) ON DELETE CASCADE, payload TEXT NOT NULL, summary TEXT, status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','superseded')), requested_by INTEGER, decided_by INTEGER, decided_at TEXT, decide_note TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_entry_items ( id INTEGER PRIMARY KEY AUTOINCREMENT, entry_id INTEGER NOT NULL REFERENCES sales_entries(id) ON DELETE CASCADE, line_no INTEGER NOT NULL DEFAULT 0, item_code TEXT, item_description TEXT, remarks TEXT, qty REAL NOT NULL DEFAULT 1, unit_price REAL NOT NULL DEFAULT 0, amount REAL NOT NULL DEFAULT 0, group_tag TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_entry_payments ( id INTEGER PRIMARY KEY AUTOINCREMENT, entry_id INTEGER NOT NULL REFERENCES sales_entries(id) ON DELETE CASCADE, paid_at TEXT NOT NULL, payment_method TEXT NOT NULL, amount REAL NOT NULL, account_sheet TEXT, approval_code TEXT, collected_by TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_orders ( id INTEGER PRIMARY KEY AUTOINCREMENT, doc_no TEXT UNIQUE NOT NULL, region TEXT NOT NULL CHECK(region IN ('WEST','EAST','SG')), transfer_to TEXT, doc_date TEXT, ref TEXT, branding TEXT, debtor_name TEXT, phone TEXT, sales_location TEXT, sales_agent TEXT, local_total REAL DEFAULT 0, balance REAL DEFAULT 0, remark2 TEXT, remark3 TEXT, remark4 TEXT, ac_udf_pdate TEXT, expiry_date TEXT, note TEXT, po_doc_no TEXT, inv_addr1 TEXT, inv_addr2 TEXT, inv_addr3 TEXT, inv_addr4 TEXT, venue TEXT, attention TEXT, sync_status TEXT DEFAULT 'SYNCED' CHECK(sync_status IN ('SYNCED','ERROR')), sync_error TEXT, last_modified TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')) , customer_email TEXT);
CREATE TABLE sales_positions ( id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL, level INTEGER NOT NULL DEFAULT 20, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_rep_brands ( rep_id INTEGER NOT NULL REFERENCES sales_reps(id) ON DELETE CASCADE, brand TEXT NOT NULL, PRIMARY KEY (rep_id, brand) );
CREATE TABLE sales_rep_commission_tiers ( id INTEGER PRIMARY KEY AUTOINCREMENT, rep_id INTEGER NOT NULL REFERENCES sales_reps(id) ON DELETE CASCADE, threshold REAL NOT NULL DEFAULT 0, rate REAL NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sales_reps ( id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, phone TEXT, email TEXT, position_id INTEGER REFERENCES sales_positions(id) ON DELETE SET NULL, upline_id INTEGER REFERENCES sales_reps(id) ON DELETE SET NULL, user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE SET NULL, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','inactive')), is_admin INTEGER NOT NULL DEFAULT 0, commission_rate REAL, commission_tier_id INTEGER REFERENCES sales_commission_tiers(id) ON DELETE SET NULL, joined_on TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), archived_at TEXT, archived_by INTEGER , nric TEXT, upline_secondary_id INTEGER REFERENCES sales_reps(id) ON DELETE SET NULL, commission_min_rate REAL NOT NULL DEFAULT 0);
CREATE TABLE sales_team_activity ( id INTEGER PRIMARY KEY AUTOINCREMENT, rep_id INTEGER NOT NULL REFERENCES sales_reps(id) ON DELETE CASCADE, action TEXT NOT NULL, from_value TEXT, to_value TEXT, note TEXT, user_id INTEGER, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE sessions ( token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires_at TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), origin TEXT, renew_seconds INTEGER, FOREIGN KEY (user_id) REFERENCES users(id) );
CREATE TABLE state_warehouse_map ( state TEXT PRIMARY KEY, warehouse TEXT NOT NULL, FOREIGN KEY (warehouse) REFERENCES warehouses(code) );
CREATE TABLE stock_items ( item_code TEXT PRIMARY KEY, auto_key TEXT, doc_key TEXT, description TEXT, desc2 TEXT, item_group TEXT, item_type TEXT, item_brand TEXT, item_class TEXT, item_category TEXT, base_uom TEXT, sales_uom TEXT, purchase_uom TEXT, main_supplier TEXT, is_active INTEGER DEFAULT 1, is_sales_item INTEGER, is_purchase_item INTEGER, lead_time INTEGER, cost REAL, price REAL, tax_code TEXT, purchase_tax_code TEXT, barcode2 TEXT, cost_code TEXT, last_modified TEXT, raw TEXT, fetched_at TEXT DEFAULT (datetime('now')), created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP );
CREATE TABLE suggestions ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, body TEXT, status TEXT NOT NULL DEFAULT 'review' CHECK (status IN ('review','approved','declined')), decided_by INTEGER REFERENCES users(id), decided_at TEXT, decline_reason TEXT, awarded_at TEXT, created_at TEXT DEFAULT (datetime('now')) , archived_at TEXT);
CREATE TABLE system_settings ( key TEXT PRIMARY KEY, value TEXT );
CREATE TABLE table_layouts ( id INTEGER PRIMARY KEY AUTOINCREMENT, company_id INTEGER NOT NULL, user_id INTEGER, table_key TEXT NOT NULL, layout TEXT NOT NULL, updated_at TEXT DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ','now')), updated_by INTEGER , name TEXT);
CREATE TABLE trip_locations ( id INTEGER PRIMARY KEY AUTOINCREMENT, trip_id INTEGER NOT NULL, lat REAL NOT NULL, lng REAL NOT NULL, accuracy REAL, recorded_at TEXT NOT NULL, FOREIGN KEY (trip_id) REFERENCES trips(id) ON DELETE CASCADE );
CREATE TABLE trip_proposal_trips ( id INTEGER PRIMARY KEY AUTOINCREMENT, proposal_id INTEGER NOT NULL, warehouse TEXT NOT NULL, trip_date TEXT NOT NULL, suggested_lorry_id INTEGER, suggested_driver_user_id INTEGER, trip_type TEXT NOT NULL DEFAULT 'delivery', total_revenue REAL DEFAULT 0, total_distance_km REAL DEFAULT 0, stop_count INTEGER DEFAULT 0, is_outsourced INTEGER NOT NULL DEFAULT 0, payload_json TEXT NOT NULL, FOREIGN KEY (proposal_id) REFERENCES trip_proposals(id) ON DELETE CASCADE );
CREATE TABLE trip_proposals ( id INTEGER PRIMARY KEY AUTOINCREMENT, generated_at TEXT NOT NULL, generated_by INTEGER, horizon_days INTEGER NOT NULL DEFAULT 7, status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','confirmed','discarded')), summary_json TEXT, notes TEXT, FOREIGN KEY (generated_by) REFERENCES users(id) );
CREATE TABLE trip_stops ( id INTEGER PRIMARY KEY AUTOINCREMENT, trip_id INTEGER NOT NULL, doc_no TEXT NOT NULL, sequence INTEGER NOT NULL DEFAULT 0, stop_type TEXT NOT NULL DEFAULT 'delivery' CHECK(stop_type IN ('delivery','service','pickup','setup','dismantle')), dismantle_session TEXT CHECK(dismantle_session IS NULL OR dismantle_session IN ('morning','night')), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','arrived','delivered','failed')), arrived_at TEXT, completed_at TEXT, recipient_name TEXT, signature_r2_key TEXT, pod_photo_r2_key TEXT, failure_reason TEXT, notes TEXT, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), UNIQUE(trip_id, doc_no), FOREIGN KEY (trip_id) REFERENCES trips(id) ON DELETE CASCADE );
CREATE TABLE trips ( id INTEGER PRIMARY KEY AUTOINCREMENT, trip_no TEXT UNIQUE NOT NULL, warehouse TEXT NOT NULL, trip_date TEXT NOT NULL, lorry_id INTEGER, driver_user_id INTEGER, status TEXT NOT NULL DEFAULT 'assigned' CHECK(status IN ('assigned','started','in_progress','completed','cancelled')), trip_type TEXT NOT NULL DEFAULT 'delivery' CHECK(trip_type IN ('delivery','setup','dismantle','sg','mixed')), is_outsourced INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','proposal')), proposal_id INTEGER, started_at TEXT, completed_at TEXT, start_odometer REAL, end_odometer REAL, fuel_litres REAL, fuel_cost REAL, total_revenue REAL DEFAULT 0, total_distance_km REAL DEFAULT 0, stop_count INTEGER DEFAULT 0, notes TEXT, created_by INTEGER, created_at TEXT DEFAULT (datetime('now')), updated_at TEXT DEFAULT (datetime('now')), helper_1_id INTEGER REFERENCES users(id), helper_2_id INTEGER REFERENCES users(id), helper_outsourced INTEGER DEFAULT 0, clock_in_at TEXT, clock_out_at TEXT, project_id INTEGER, FOREIGN KEY (warehouse) REFERENCES warehouses(code), FOREIGN KEY (lorry_id) REFERENCES lorries(id), FOREIGN KEY (driver_user_id) REFERENCES users(id), FOREIGN KEY (created_by) REFERENCES users(id) );
CREATE TABLE udf_fields ( id INTEGER PRIMARY KEY AUTOINCREMENT, table_name TEXT NOT NULL, field_key TEXT NOT NULL, label TEXT NOT NULL, field_type TEXT NOT NULL DEFAULT 'text' CHECK(field_type IN ('text','number','date','select','checkbox')), options TEXT, position INTEGER DEFAULT 0, created_at TEXT DEFAULT (datetime('now')), UNIQUE(table_name, field_key) );
CREATE TABLE udf_values ( table_name TEXT NOT NULL, row_key TEXT NOT NULL, field_key TEXT NOT NULL, value TEXT, updated_at TEXT DEFAULT (datetime('now')), PRIMARY KEY (table_name, row_key, field_key) );
CREATE TABLE user_brands ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, brand TEXT NOT NULL, created_at TEXT DEFAULT (datetime('now')), PRIMARY KEY (user_id, brand) );
CREATE TABLE user_streak_weeks ( user_id INTEGER NOT NULL REFERENCES users(id), iso_week TEXT NOT NULL, upvotes_count INTEGER NOT NULL DEFAULT 0, qualified INTEGER NOT NULL DEFAULT 0, computed_at TEXT DEFAULT (datetime('now')), PRIMARY KEY (user_id, iso_week) );
CREATE TABLE users ( id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT UNIQUE NOT NULL, name TEXT, password_hash TEXT, role_id INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','active','disabled')), invited_by INTEGER, invited_at TEXT, joined_at TEXT, last_login_at TEXT, last_seen_at TEXT, created_at TEXT DEFAULT (datetime('now')), user_type TEXT DEFAULT 'staff' CHECK(user_type IN ('staff','driver','helper','dispatcher','admin')), phone TEXT, ic_number TEXT, license_no TEXT, license_expiry TEXT, emergency_contact_name TEXT, emergency_contact_phone TEXT, base_salary REAL DEFAULT 0, trip_allowance_rate REAL DEFAULT 0, ot_rate REAL DEFAULT 0, max_continuous_hours REAL DEFAULT 8, manager_id INTEGER REFERENCES users(id) ON DELETE SET NULL, department_id INTEGER REFERENCES departments(id) ON DELETE SET NULL, points_balance INTEGER NOT NULL DEFAULT 0, gifting_balance INTEGER NOT NULL DEFAULT 0, gifting_reset_at TEXT, current_streak INTEGER NOT NULL DEFAULT 0, profile_pic_r2_key TEXT, position_id INTEGER REFERENCES positions(id), totp_secret TEXT, totp_enabled INTEGER NOT NULL DEFAULT 0, totp_enrolled_at TEXT, totp_backup_codes TEXT, company_phone TEXT, email_alias TEXT, last_path TEXT, FOREIGN KEY (role_id) REFERENCES roles(id) );
CREATE TABLE votes ( id INTEGER PRIMARY KEY AUTOINCREMENT, target_type TEXT NOT NULL CHECK (target_type IN ('innovation','suggestion')), target_id INTEGER NOT NULL, user_id INTEGER NOT NULL REFERENCES users(id), created_at TEXT DEFAULT (datetime('now')), UNIQUE (target_type, target_id, user_id) );
CREATE TABLE warehouses ( code TEXT PRIMARY KEY, name TEXT NOT NULL, address TEXT, lat REAL, lng REAL, is_active INTEGER NOT NULL DEFAULT 1 );
