CREATE TRIGGER trg_project_venues_canonicalize_name_ins AFTER INSERT ON project_venues FOR EACH ROW WHEN NEW.name IS NOT NULL AND NEW.name <> '2990s PJ' AND lower(trim(NEW.name)) IN ('pj showroom','pj-showroom','pjshowroom','2990s pj','2990spj','2990 pj','2990pj') BEGIN UPDATE project_venues SET name = '2990s PJ' WHERE id = NEW.id; END;
CREATE TRIGGER trg_project_venues_canonicalize_name_upd AFTER UPDATE OF name ON project_venues FOR EACH ROW WHEN NEW.name IS NOT NULL AND NEW.name <> '2990s PJ' AND lower(trim(NEW.name)) IN ('pj showroom','pj-showroom','pjshowroom','2990s pj','2990spj','2990 pj','2990pj') BEGIN UPDATE project_venues SET name = '2990s PJ' WHERE id = NEW.id; END;
CREATE TRIGGER trg_projects_canonicalize_venue_ins AFTER INSERT ON projects FOR EACH ROW WHEN NEW.venue IS NOT NULL AND NEW.venue <> '2990s PJ' AND lower(trim(NEW.venue)) IN ('pj showroom','pj-showroom','pjshowroom','2990s pj','2990spj','2990 pj','2990pj') BEGIN UPDATE projects SET venue = '2990s PJ' WHERE id = NEW.id; END;
CREATE TRIGGER trg_projects_canonicalize_venue_upd AFTER UPDATE OF venue ON projects FOR EACH ROW WHEN NEW.venue IS NOT NULL AND NEW.venue <> '2990s PJ' AND lower(trim(NEW.venue)) IN ('pj showroom','pj-showroom','pjshowroom','2990s pj','2990spj','2990 pj','2990pj') BEGIN UPDATE projects SET venue = '2990s PJ' WHERE id = NEW.id; END;
